  /* 7×7 grids 子盘 */
  .fruit-grid {
    display:grid; grid-template-columns:repeat(7,minmax(0,1fr)); gap:5px;
    grid-template-rows:repeat(7,minmax(0,1fr));
    padding:9px; border-radius:8px;
    background:linear-gradient(180deg,#2a0609,#16030a);
