  /* 经典Prize格子：象牙底 + 金属金边 + 微凹内阴影 */
  .fruit-cell {
    position:relative; aspect-ratio:1/1; border-radius:5px;
    background:linear-gradient(160deg,#fffdf0,#f5ecc8 55%,#e8d8a8);
